def U(claim, reason, kind='factual', numeric='not_numeric'):
    return dict(claim=claim,claim_type=kind,classification='Unsupported',numeric_status=numeric,evidence=[],reason=reason)


def S(claim, lines, reason, numeric='not_numeric',kind='factual'):
    return dict(claim=claim,claim_type=kind,classification='Supported',numeric_status=numeric,
                evidence=[dict(line_start=a,line_end=b) for a,b in lines],reason=reason)


def C(claim,lines,reason,numeric='incorrect',kind='quantitative'):
    result=S(claim,lines,reason,numeric,kind);result['classification']='Contradicted';return result


def us(reason,*claims,kind='factual'):
    return [U(c,reason,kind) for c in claims]


