def main():
    run=Path('runs/NVDA_baseline_1')
    manifest,inputs=load_inputs(run)
    sections={}
    for section,item in inputs.items():
        units=source_units(item['text']);review=reviews[section]
        if set(review)!=set(range(len(units))):
            raise ValueError((section,'Explicit review coverage mismatch',set(review),len(units)))
        sections[section]={'source_sha256':item['metadata']['source_sha256'],
            'evidence_sha256':item['metadata']['evidence_prompt_sha256'],
            'units':[{'unit_id':i,'atoms':review[i],
                'nonfactual_reason':('Heading or a pure valuation/research recommendation with no additional independently testable premise; factual premises in other units are audited separately.' if not review[i] else '')} for i in range(len(units))]}
    spec={'protocol_version':'machine-adjudication-v1','run_id':manifest['run_id'],'evidence_run_id':manifest['run_id'],
          'raw_judge_audit':'audits/grounding/NVDA_before_gpt41','sections':sections}
    path=Path('audits/machine_adjudication/NVDA_before_review.json');path.parent.mkdir(parents=True,exist_ok=True)
    path.write_text(json.dumps(spec,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
    print('Explicit NVDA baseline review specification:',sum(len(a) for section in reviews.values() for a in section.values()),'atomic claims')


if __name__=='__main__':main()
